unsigned aleatorio=12345;
auto sorteio=[&](){aleatorio=aleatorio*1664525u+1013904223u;return aleatorio;};
for(int teste=0;teste<250;++teste){
 int n=2+sorteio()%5,K=sorteio()%3;
 vector<vector<ArestaFim>> gr(n);
 for(int u=0;u<n;++u)for(int v=0;v<n;++v)if(u!=v && sorteio()%3==0){
  long long w=sorteio()%10,extra=(sorteio()%2 ? (long long)(sorteio()%10) : -1);
  gr[u].push_back({v,w,extra});
 }
 // Oráculo independente: Bellman-Ford no grafo de estados materializado.
 int S=n*(K+1);vector<long long>d(S,1000000);d[0]=0;
 for(int passo=0;passo<S-1;++passo)for(int u=0;u<n;++u)for(int k=0;k<=K;++k){
  int origem=u*(K+1)+k;if(d[origem]==1000000)continue;
  for(auto e:gr[u]){
   int normal=e.v*(K+1)+k;d[normal]=min(d[normal],d[origem]+e.normal);
   if(k<K && e.extra>=0){int alt=normal+1;d[alt]=min(d[alt],d[origem]+e.extra);}
  }
 }
 long long esperado=1000000;
 for(int k=0;k<=K;++k)esperado=min(esperado,d[(n-1)*(K+1)+k]);
 if(esperado==1000000)esperado=-1;
 assert(ateDestino(gr,K)==esperado);
}

