for(int teste=0;teste<250;++teste){
 int tamanho=1+sorteio()%10;
 vector<char> tipos(tamanho);vector<int> deps(tamanho);
 vector<pair<long long,long long>> intervalos(tamanho);
 for(int i=0;i<tamanho;++i){
  tipos[i]=string("ADT")[sorteio()%3];deps[i]=(int)(sorteio()%(tamanho+1))-1;
  intervalos[i]={2*i,2*i+3};
 }
 auto got=resolver(tipos,deps,intervalos);
 for(int inicio=0;inicio<tamanho;++inicio){
  // Oráculo sem memoização: segue a cadeia individual até resposta ou repetição.
  vector<bool> vistos(tamanho);int u=inicio;Presenca esperado;
  while(u!=-1 && !vistos[u]){
   vistos[u]=true;
   if(tipos[u]=='A'){esperado={true,intervalos[u].first,intervalos[u].second};break;}
   if(tipos[u]=='D')break;
   u=deps[u];
  }
  assert(got[inicio].vai==esperado.vai);
  if(esperado.vai)assert(got[inicio].inicio==esperado.inicio && got[inicio].fim==esperado.fim);
 }
}

